static Entity Actor(World& world,const std::string& name,const std::string& script){auto e=world.CreateEntity();world.AddComponent<TransformComponent>(e);world.AddComponent<TagComponent>(e).name=name;world.AddComponent<SceneIdentityComponent>(e);world.AddComponent<LuaScriptComponent>(e).scriptPath=script;return e;}
static auto Ref(World& w,Entity e){return nlohmann::json{{"$entity",w.GetComponent<SceneIdentityComponent>(e)->value}};}
static const char* sender=R"(return {fields={target={type='entity'}},on_start=function(self) self.timer=Timer.after(0.5,'tick') end,
 on_update=function(self) if World.get_position(self.entity).x>0 then World.send_event(self.target,'toggle',3);World.set_position(self.entity,Vec3.new(0,0,0)) end end,
 on_event=function(self,e) if e.type=='tick' then World.send_event(self.target,'timer_toggle',2) end end})";
static const char* receiver=R"(return {on_event=function(self,e) World.set_position(self.entity,Vec3.new(e.amount,0,0)) end})";
static void Send(LuaRuntime& lua,World& w,Entity e){w.GetComponent<TransformComponent>(e)->position.x=1;lua.Update(0);lua.Update(0);}
